<script setup>
import { computed, onMounted, ref } from 'vue'
import { withBase } from 'vitepress'
import { data as tutorials } from '../tutorials.data.js'
import { data as siteMeta } from '../siteMeta.data.js'
import { lectureImages, lectureCardImages } from '../lectureImages.js'
import { loadManifest, loadGroupPapers, loadTaxonomy } from '../radarData.js'
const selected = ref(tutorials.at(-1)?.slug || '')
const lecture = computed(() => tutorials.find(t => t.slug === selected.value))
const manifest = ref(null), papers = ref([]), day = ref(''), taxonomy = ref(null), error = ref('')
const days = computed(() => [...new Set(papers.value.filter(p=>p.relevance===3).map(p=>p.published_date))].sort().reverse().slice(0,4))
const core = computed(() => papers.value.filter(p=>p.relevance===3 && p.published_date===day.value))
const count = computed(()=>manifest.value?.total_papers ?? '—')
const shortDate = d => `${Number(d.slice(5,7))} 月 ${Number(d.slice(8))} 日`
const weekday = d => new Intl.DateTimeFormat('zh-CN',{weekday:'short', timeZone:'UTC'}).format(new Date(`${d}T00:00:00Z`))
const domain = id => taxonomy.value?.finance_domains?.get(id) || id
const meta = p => [p.finance_domains.map(domain).join('、'), p.venue?.name, p.affiliations.slice(0,2).join(' · ')].filter(Boolean).join(' · ')
function moveLecture(e,i) { if(!['ArrowRight','ArrowDown','ArrowLeft','ArrowUp'].includes(e.key))return;e.preventDefault(); const n=(i+(['ArrowRight','ArrowDown'].includes(e.key)?1:-1)+tutorials.length)%tutorials.length;selected.value=tutorials[n].slug;document.getElementById(`pick-${selected.value}`)?.focus() }
function moveDay(e,i) { if(!['ArrowRight','ArrowDown','ArrowLeft','ArrowUp'].includes(e.key))return;e.preventDefault();day.value=days.value[(i+(['ArrowRight','ArrowDown'].includes(e.key)?1:-1)+days.value.length)%days.value.length];document.getElementById(`day-${day.value}`)?.focus() }
onMounted(async()=>{try{const [m,p,t]=await Promise.all([loadManifest(),loadGroupPapers('recent'),loadTaxonomy()]);manifest.value=m;papers.value=p.sort((a,b)=>b.published_date.localeCompare(a.published_date));taxonomy.value=t;day.value=days.value[0]||''}catch{error.value='论文数据暂时没有加载成功，可前往论文雷达重试。'}})
</script>
<template><div class="content-view home"><main id="main">
<section class="hero page" aria-labelledby="home-title"><div class="hero-talk"><p class="hero-sentence">做量化研究、做 AI + 金融要用到的资源，都整理在这里：开源项目和研报论文，全网 AI × 金融研究的一站式阅读，还有和 AI 一起动手的量化研究教程。</p><a class="btn btn-accent hero-action" :href="withBase('/resources/')">看开源资源清单</a><p class="hero-by">湖南大学金融科技协会 Quant Group 开源维护</p></div><div class="hero-main"><h1 id="home-title" class="mask-title"><span class="line"><span>量化研究入门</span></span><span class="line"><span>与AI+金融</span></span></h1><figure class="hero-fig"><span class="fig-box"><img :src="withBase('/site/hero-size-effect.webp')" alt="A 股按市值分十组的累计净值（对数刻度，2000—2025）" width="1600" height="780" fetchpriority="high"></span><figcaption>十组与规模多空累计净值（等权，2000—2025），出自<a :href="withBase('/tutorials/02-size-value-effects/')">实战二：中国股票市场的价值效应与规模效应</a>。</figcaption></figure></div></section>
<section class="home-overview page" aria-labelledby="h-overview"><h2 id="h-overview">这里有什么</h2><ol class="ledger overview-ledger">
<li class="ov-row"><h3 class="ov-name">量化研究资源</h3><p class="ov-desc">开源项目、回测框架、数据接口、因子挖掘和机器学习工具，按 {{ siteMeta.categories }} 个类别整理，每项附一句推荐理由；另有研究框架、数据、因子、回测、组合等研究方法笔记。仓库还收藏了卖方金工研报和学术论文，按系列和主题建目录，每份都链到 GitHub 上的原文件。</p><div class="ov-side"><p class="ov-nums num">{{ siteMeta.resources }} 个开源项目<br>{{ siteMeta.methods }} 篇方法笔记<br>{{ siteMeta.reports.count }} 份研报<br>{{ siteMeta.papers.count }} 篇论文</p><p class="ov-links"><a class="text-link" :href="withBase('/resources/')">开源资源清单</a><a class="text-link" :href="withBase('/library/')">研报与论文</a></p></div></li>
<li class="ov-row"><h3 class="ov-name">AI × 金融前沿论文</h3><p class="ov-desc">聚焦 AI 在金融里的应用，把全网的 AI × 金融研究放在一处读。论文自动收集、自动更新：计算机方向的论文来自 arXiv，金融方向来自 NBER 工作论文和顶会录用名单，SSRN 等来源计划接入。每篇配一句中文概括和分类。</p><div class="ov-side"><p class="ov-nums num">已收录 {{ count }} 篇</p><p class="ov-links"><a class="text-link" :href="withBase('/arxiv/')">一站式阅读</a></p></div></li>
<li class="ov-row"><h3 class="ov-name">和 AI 一起学的量化研究教程</h3><p class="ov-desc">每一讲是一项完整的小研究，从数据准备到跑出结果并解读，每一步都附上给 AI 编程工具的参考提示词。讲义是协会在做项目的过程中积累下来的，之后会有更多来自贡献者和协会自己的项目，欢迎投稿。</p><div class="ov-side"><p class="ov-nums num">{{ tutorials.length }} 讲</p><p class="ov-links"><a class="text-link" :href="withBase('/tutorials/')">看讲义</a></p></div></li>
</ol></section>
<section v-if="lecture" class="home-lectures page" aria-labelledby="h-lectures"><div class="lect-pick"><h2 id="h-lectures">教程：和 AI 一起复现顶刊论文的想法</h2><p class="sec-sub">每一讲挑一篇经典论文或券商研报的想法，用中国市场的数据从头复现一遍：从数据准备讲起，一步步实现、跑出结果并解读。每一步都附上给 AI 编程工具的参考提示词，你和 AI 一起把代码写出来，再一起检查结果对不对。</p><div class="picks" role="tablist" aria-label="讲义"><button v-for="(t,i) in tutorials" :key="t.slug" type="button" class="pick" role="tab" :id="`pick-${t.slug}`" :aria-controls="`sheet-${t.slug}`" :aria-selected="selected===t.slug" :tabindex="selected===t.slug?0:-1" @click="selected=t.slug" @keydown="moveLecture($event,i)"><span class="pick-img"><img v-if="lectureImages[t.slug]" :src="lectureImages[t.slug]" alt="" width="1600" height="1024" loading="lazy"></span><span class="pick-n">{{ t.title.split(/[：:]/)[0] }}</span><span class="pick-t">{{ t.title.replace(/^实战[一二三四五六七八九十]+[：:]/,'') }}</span></button></div><a class="text-link" :href="withBase('/tutorials/')">全部讲义和学习顺序</a></div><div class="stage"><div class="sheet" :id="`sheet-${lecture.slug}`" role="tabpanel" :aria-labelledby="`pick-${lecture.slug}`"><h3>{{ lecture.title }}</h3><p class="sheet-level">{{ lecture.level }}<span v-if="lecture.slug===tutorials.at(-1)?.slug" class="latest">最新一讲</span></p><p class="sheet-desc">{{ lecture.description }}</p><figure v-if="lectureCardImages[lecture.slug]" class="sheet-fig"><img :src="lectureCardImages[lecture.slug]" :alt="lecture.title + '图表'" width="1600" height="1024" loading="lazy"></figure><dl class="sheet-meta"><div><dt>先修</dt><dd>{{ lecture.prerequisites }}</dd></div><div><dt>数据</dt><dd>{{ lecture.data }}</dd></div><div><dt>整理</dt><dd>{{ lecture.author }}</dd></div></dl><p class="sheet-steps-h">这一讲的步骤</p><ol class="sheet-steps"><li v-for="s in lecture.steps" :key="s">{{ s }}</li></ol><a class="text-link" :href="withBase(lecture.url)">读这一讲</a></div></div></section>
<section class="home-radar page" aria-labelledby="h-radar"><div class="radar-head"><div><h2 id="h-radar">AI × 金融论文雷达 FinPaperRadar</h2><p class="sec-sub">全网的 AI × 金融研究，在一个地方读完。论文自动抓取、自动更新：计算机方向的论文来自 arXiv，金融方向来自 NBER 工作论文和顶会录用名单，SSRN 等来源计划接入。每篇配一句中文概括和分类，已收录 <span class="num">{{ count }}</span> 篇。下面是最近几天的核心论文。</p></div><a class="btn btn-ink" :href="withBase('/arxiv/papers')">打开论文雷达</a></div><p v-if="error" class="index-note" role="status">{{ error }}</p><div v-else-if="days.length" class="radar-board"><div class="days" role="tablist" aria-label="日期"><button v-for="(d,i) in days" :key="d" type="button" class="day" role="tab" :id="`day-${d}`" aria-controls="home-paper-band" :aria-selected="day===d" :tabindex="day===d?0:-1" @click="day=d" @keydown="moveDay($event,i)"><span class="day-d">{{ shortDate(d) }}</span><span class="day-w">{{ weekday(d) }} · <span class="num">{{ papers.filter(p=>p.relevance===3 && p.published_date===d).length }}</span> 篇核心</span></button></div><ol class="band-list" id="home-paper-band" role="tabpanel" :aria-labelledby="`day-${day}`"><li v-for="p in core.slice(0,4)" :key="p.id" class="band"><a class="band-title serif" :href="p.abs_link" target="_blank" rel="noopener" lang="en">{{ p.title }}</a><p class="band-tldr">{{ p.tldr_zh }}</p><p class="band-meta">{{ meta(p) }}</p></li></ol></div><p v-else class="index-note" role="status">正在加载最近的论文。</p></section>
</main></div></template>
